import sys
ARGS = [a.lower() for a in sys.argv[1:]]
RAW = "raw" in ARGS     # 素のLLM: ゲームの説明とログだけを渡す(指示・人格・台帳なし)。単純な版の一種
SIMPLE = "simple" in ARGS or RAW   # 単純な版: 1回の呼び出しで、ログと短い指示から1発言を書く(読む係・3案・検証・統計・台帳・後処理の大半を使わない)
if SIMPLE:
    ARGS += ["slim", "nofree", "novoice", "noverify", "nostats", "nohyouki"] + ([] if "seitou" in ARGS else ["noprinciples"])
    REACT = False   # 反射の短い反応(別の呼び出し)も使わない
    OPENER_ON = False  # 夜のうちに作り置きする「起点の一言」も使わない(流れを見ずに投稿され、時系列の取り違えの元になったため)
    ANALYST = False  # 裏の考える係も使わない(単純な版のプロンプトには入らないので、料金の無駄になる)
TYPING_WAIT = TYPING_WAIT or "typing" in ARGS   # typing を付けると、打っている時間の演出を戻す
KEYS_PER_SEC = next((float(a[5:]) for a in ARGS if a.startswith("keys=") and a[5:].replace(".", "").isdigit()), 0)
if KEYS_PER_SEC:   # keys=16 … 1秒16打鍵の人が打つのにかかる時間だけ待ってから投稿する(考えていた時間は差し引く)
    TYPING_WAIT, TYPING_MAX = True, 40


def typing_seconds(text):
    """打つのにかかる秒数。keys= があれば打鍵数(かな・漢字は1字2打鍵、英数字・記号は1打鍵として数える)÷打鍵の速さ。"""
    if KEYS_PER_SEC:
        keys = sum(1 if ord(c) < 128 else 2 for c in text)
        return min(keys / KEYS_PER_SEC, TYPING_MAX)
    return min(len(text) / TYPING_SPEED, TYPING_MAX)
QUIET = "quiet" in ARGS     # 控えめに話す(selfplay の相手役用): 短く・間をあけて話す
