CHAT_LONG_RATE = 0.2   # 雑談で長めに話してよい割合(5回に1回くらい)


def fit_length(text, limit=MAX_CHARS):
    """改行を消し、上限を超えたら文の区切り(。!?)で切りそろえる。"""
    text = " ".join(text.split())
    if len(text) <= limit:
        return text
    cut = text[:limit]
    ends = [cut.rfind(c) for c in "。!?！？"]
    end = max(ends)
    if end >= limit // 2:          # 区切りが前半すぎなければそこで切る
        return cut[:end + 1]
    return cut[:limit - 1] + "…"


def load_examples():
    p = Path(EXAMPLES_FILE) if EXAMPLES_FILE else None
    if not p or not p.is_file():
        return []
    return [l.strip() for l in p.read_text(encoding="utf-8").splitlines() if l.strip()]


def load_glossary():
    """glossary.txt を読み、(必ず渡すか, 用語リスト, 1行) のリストにする。"""
    p = Path(GLOSSARY_FILE)
    if not p.exists():
        return []
    entries = []
    for line in p.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line or line.startswith("#") or ":" not in line:
            continue
        core = line.startswith("*")
        line = line.lstrip("*").strip()
        terms = [t.strip() for t in line.split(":", 1)[0].split("/") if t.strip()]
        entries.append((core, terms, line))
    return entries


EXAMPLES = load_examples()
GLOSSARY = load_glossary()


def pick_glossary(text):
    """必ず渡す語 + ログ中に出てきた語だけを選ぶ(用語集が大きくても遅くならないように)。"""
    return [line for core, terms, line in GLOSSARY
            if core or any(t in text for t in terms)]


def choose_examples():
    if not EXAMPLES or N_EXAMPLES <= 0:
        return ""
    picks = random.sample(EXAMPLES, min(N_EXAMPLES, len(EXAMPLES)))
    return ("【お手本の発言(口調だけ真似る)】\n"
            + "\n".join(f"「{fit_length(t, EXAMPLE_CHARS)}」" for t in picks))


FIXED_BLOCK = choose_examples() if FIXED_EXAMPLES else None


def load_flow():
    """「直前の流れ → 強いプレイヤーの返し」のお手本。口調ではなく、流れへの返し方(何を拾い、何を流すか)を見せる。"""
    f = PERSONAS[PERSONA].get("flow")
    if not f or "noflow" in ARGS:
        return ""
    try:
        body = Path(f).read_text(encoding="utf-8").strip()
    except OSError:
        return ""
    who = "〈自分〉"
    m = re.match(r"お手本の人: (.+)\n", body)
    if m:
        who = m.group(1).strip()
        body = body[m.end():].strip()
    FLOW_WHO[0] = who
    return (f"【お手本: 強いプレイヤー「{who}」の、実際の試合での「直前の流れ → 返し」】\n"
            f"「→ {who}」の行が、その流れを受けて{who}が実際に言ったこと。{who}が流れのどの発言を拾い、どれを流し、"
            "どの長さで、どんな考え方・言い方で返しているかを真似る(あなたは今その立場で話す)。"
            "例の話題や言い回しをそのまま使わない。お手本に出てくる人の名前は今の試合とは関係ない。"
            f"[ ]は昼のどのあたりか・{who}の役職。「／」は短い連投の区切り。\n\n" + body)


FLOW_WHO = ["〈自分〉"]
FLOW_BLOCK = load_flow()


def load_rules():
    try:
        lines = Path(RULES_FILE).read_text(encoding="utf-8").splitlines()
    except (OSError, TypeError):
        return ""
    body = "\n".join(l for l in lines if l.strip() and not l.startswith("#"))
    return ("【この村のおきて(必ず守る。おきてと他の指示が食い違ったら、おきてを優先する)】\n" + body) if body else ""


RULES = load_rules()
