# ---- 似た場面を探す(全部のログを使うため) ----
BANK = {"rows": [], "vecs": [], "idf": {}}
N_SIMILAR = 6          # 発言のたびに見せる「似た場面」の数


def _grams(text):
    t = re.sub(r"[\s、。！？!?ｗw「」『』()（）>＞]+", "", text)
    return [t[i:i + 2] for i in range(len(t) - 1)]


def _vec(lines):
    """直前の発言たちを文字2-gramの重みつき集計にする(最後の方の発言ほど重い)。名前は使わない。"""
    v = {}
    n = len(lines) or 1
    for i, t in enumerate(lines):
        w = 1.0 + 2.0 * (i + 1) / n   # 最新の発言が一番重い
        for g in _grams(t):
            v[g] = v.get(g, 0) + w
    return v


def load_bank():
    import math
    f = PERSONAS[PERSONA].get("bank")
    if not f or "noflow" in ARGS or "nobank" in ARGS:
        return
    try:
        rows = [json.loads(l) for l in Path(f).read_text(encoding="utf-8").splitlines() if l.strip()]
    except OSError:
        return
    vecs = [_vec([t for _, t in r["ctx"]]) for r in rows]
    df = {}
    for v in vecs:
        for g in v:
            df[g] = df.get(g, 0) + 1
    idf = {g: math.log((1 + len(vecs)) / (1 + c)) + 1 for g, c in df.items()}
    BANK.update(rows=rows, vecs=[{g: c * idf[g] for g, c in v.items()} for v in vecs], idf=idf)


def similar_scenes(flow_texts, k=N_SIMILAR, tag=None):
    """今の流れ(直近の発言の本文)に似た場面を、全部の組から k 個選ぶ。
    場面の札(tag)が分かっていれば、同じ札の場面を先に選ぶ(言葉が似ているだけの場面より、状況が同じ場面を見せる)。"""
    if not BANK["rows"] or not flow_texts:
        return []
    q = {g: c * BANK["idf"].get(g, 1.0) for g, c in _vec(flow_texts).items()}
    qn = sum(x * x for x in q.values()) ** 0.5 or 1.0
    scored = []
    for r, v in zip(BANK["rows"], BANK["vecs"]):
        dot = sum(c * v.get(g, 0) for g, c in q.items())
        vn = sum(x * x for x in v.values()) ** 0.5 or 1.0
        scored.append((dot / (qn * vn), r))
    scored.sort(key=lambda x: -x[0])
    if tag:
        same = [r for _, r in scored if r.get("tag") == tag]
        rest = [r for _, r in scored if r.get("tag") != tag]
        return (same[:k] + rest)[:k]
    return [r for _, r in scored[:k]]


SITUATIONS = {
    "A": "自分の冗談・ネタ・軽口を、相手が本気で詰めてきた",
    "B": "自分が疑われている・自分の主張に反論されている",
    "C": "他の人の理屈や主張に穴・飛躍がある",
    "D": "雑談・ネタ・言葉遊びが流れている",
    "E": "自分が質問された・説明や意見を求められた",
    "F": "誰を吊るか・票先を決める流れ",
    "G": "他の2人が言い合っていて、自分は外から見ている",
    "H": "その他",
}


def situation_tag(vis, me):
    """今の流れがどんな場面かを、速いモデルで札1つにする(似た場面を探すため。build_playbook.py の札と同じ)。"""
    if not any("tag" in r for r in BANK["rows"]) or BACKEND != "claude":
        return None
    lines = "\n".join(f"{m['from_user']}: {m['text'][:100]}" for m in vis if m["from_user"] not in ("鯖", "人狼"))
    lines = "\n".join(lines.splitlines()[-6:])
    menu = "\n".join(f"{k}: {v}" for k, v in SITUATIONS.items())
    try:
        out, _ = llm("", f"人狼ゲームのチャット。「{me}」から見て、最後の流れはどんな状況か、札を1つ選ぶ。\n{menu}\n\n{lines}\n\n答えは札の英字1文字だけ。",
                     max_tokens=10, temperature=0, think=False, model=REACT_MODEL)
    except Exception:
        return None
    m = re.search(r"[A-H]", out or "")
    return m.group(0) if m else None


def similar_block(vis, me):
    talk = [m["text"] for m in vis if m["from_user"] not in ("鯖", "人狼")][-6:]
    tag = situation_tag(vis, me)
    SCENE_TAG[0] = tag
    picks = similar_scenes(talk, tag=tag)
    if tag:
        print(f"  (場面の札: {tag} {SITUATIONS.get(tag, '')})")
    if not picks:
        return ""
    who = FLOW_WHO[0]
    parts = []
    for r in picks:
        ctx = "\n".join(f"{w}: {t[:120]}" for w, t in r["ctx"][-4:])
        parts.append(f"[{r['phase']}・{r['role']}]\n{ctx}\n→ {who}: {' ／ '.join(r['reply'])}")
    return (f"\n\n【今の流れに似た場面で、{who}が実際に返したこと(考え方の参考。言い回し・話題はそのまま使わない)】\n"
            + "\n\n".join(parts))


