# ---- 本人の統計に合わせる(style_stats.json。build_style_stats.py で作る) ----
#   長さ: 発言のたびに本人の長さの分布からくじを引いて、「今回は〇字以内」と伝える(中央値15字・36%が10字以内)
#   癖: 直近の自分の発言で、本人より多すぎる・少なすぎる癖(ｗ・読点・私・「んだよな」など)を伝えて直させる
#   後処理: 多すぎる癖(ｗ・読点・私は・んだよな)は、直近の割合が本人の2倍を超えたら取る
#   nostats … 使わない
STATS_ON = "nostats" not in ARGS


def load_style_stats():
    try:
        return json.loads(Path("style_stats.json").read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {}


STATS = load_style_stats() if STATS_ON else {}
BUDGET = [None]


def pick_budget():
    probs, edges = STATS.get("len_buckets"), STATS.get("len_edges")
    by_phase = (STATS.get("len_buckets_phase") or {}).get(PHASE.get("name") or "")
    if by_phase:
        probs = by_phase   # 序盤は短く(中央値11字)、中盤・終盤は長め(中央値24字)。本人の返しを場面ごとに数えた分布
    if not probs or not edges:
        return None
    caps = list(edges) + [random.choice((80, 110, 140, 170))]   # 60字を超える番(本人で2割ほど)は長さにも幅がある(最長194字)
    r, acc = random.random(), 0.0
    for pr, cap in zip(probs, caps):
        acc += pr
        if r <= acc:
            return cap
    return caps[-1]


def style_gaps(mine):
    """直近の自分の発言と本人の統計の差。多すぎる・少なすぎる癖を文にする。"""
    feats = STATS.get("features") or {}
    if len(mine) < 8 or not feats:
        return ""
    out = []
    lens = sorted(len(t) for t in mine)
    med = lens[len(lens) // 2]
    if STATS.get("len_median") and med > STATS["len_median"] * 1.8:
        out.append(f"・長さ(中央値): あなた{med}字 / 本人{STATS['len_median']}字(長い。短く切る)")
    for name, f in feats.items():
        rx = re.compile(f["pattern"])
        cur = sum(bool(rx.search(t)) for t in mine) / len(mine)
        real = f["rate"]
        if cur >= max(real * 2, real + 0.08):
            out.append(f"・{f['desc']}: あなた{cur:.0%} / 本人{real:.0%}(多い。減らす)")
        elif real >= 0.04 and cur <= real * 0.3:
            out.append(f"・{f['desc']}: あなた{cur:.0%} / 本人{real:.0%}(少ない)")
    return "\n".join(out[:6])


def style_prompt(msgs, name):
    """プロンプトに足す『今回の長さ』と『癖の差』。"""
    BUDGET[0] = None
    if not STATS:
        return ""
    cap = pick_budget()
    if cap and unanswered_to_me(msgs, name):
        cap = max(cap, 40)    # 質問に答えるときは、短すぎて答えられなくならないようにする
    BUDGET[0] = cap
    mine = [m["text"] for m in current_game(msgs) if m["from_user"] == name and m["to_user"] == "ALL"][-30:]
    txt = ""
    if cap and cap > 60:
        longs = long_examples()
        target = int(cap * 0.85)
        txt += (f"\n\n【今回の長さ】長文の番(目安{target}字前後。少なくとも{int(cap * 0.6)}字、多くても{cap}字)。本人がときどき書く長い考察のように、相手の言葉を引いて、"
                "理由を重ねて、自分の結論まで1つの発言で書き切る(細かく区切らない)。"
                "この番は3案の作り方を変える: 3案のうち2つをこの長さの長文にし(言い方・理由の並べ方を変える)、残り1つだけ短い言い方にする。"
                "長文の案の少なくとも1つは、読解メモの【主張の設計】の具体例(無ければ自分で、相手の理屈を別の発言に当てはめる・たとえ・頭の中の言葉を「」で見せる、のどれか)で押す。"
                + ("本人の長文の例(言い回しはまねない):\n" + "\n".join(f"・{t}" for t in longs) if longs else ""))
    elif cap:
        txt += (f"\n\n【今回の長さ】{cap}字以内(本人の長さの分布からくじで決めた。入りきらないなら一番大事な1点だけ言う。"
                "短く言い切れるなら、もっと短くてよい)")
    gaps = style_gaps(mine)
    if gaps:
        txt += "\n【直近のあなたの発言と本人の差(多いものは減らす・少ないものは自然な所で足す)】\n" + gaps
    return txt


LONG_POOL = [None]


def long_examples(k=2):
    """本人の実際の長文(80〜190字)を k 件。毎回くじで選ぶ。"""
    if LONG_POOL[0] is None:
        who = FLOW_WHO[0]
        LONG_POOL[0] = [t.strip().replace("\n", " / ") for g in persona_games() for w, t in g["day"]
                        if w == who and 80 <= len(t.strip()) <= 190 and not NOT_SHARP_RE.search(t)]
    pool = LONG_POOL[0]
    return random.sample(pool, min(k, len(pool))) if pool else []


def _outside_quotes(speech, fn):
    """「」の中(貼った引用)は触らずに fn を当てる。"""
    return "".join(x if x.startswith("「") else fn(x) for x in re.split(r"(「[^」]*」)", speech))


def fit_budget(speech):
    """くじで引いた長さを大きく超えていたら、文の区切りで後ろを切る(引用つきの発言は切らない)。"""
    cap = BUDGET[0]
    if not cap or "「" in speech or len(speech) <= cap * 1.3 + 6:
        return speech
    out = ""
    for sent in split_sentences(speech):
        if out and len(out) + len(sent) > cap * 1.3 + 6:
            break
        out += sent
    return out.strip() or speech


def style_quota(speech, mine):
    """直近の割合が本人の2倍を超えている癖を、この発言から取る(ｗ・読点・私は・んだよな)。"""
    feats = STATS.get("features") or {}
    recent = mine[-30:]
    if not feats or not speech or len(recent) < 6:
        return speech

    def over(key):
        f = feats.get(key)
        if not f:
            return False
        rx = re.compile(f["pattern"])
        return sum(bool(rx.search(t)) for t in recent) / len(recent) > max(f["rate"] * 2, f["rate"] + 0.05)
    if re.search(r"[ｗw]{3,}", speech):
        pass   # 感情の爆発のｗは残す(割合は burst_quota で見ている)
    elif over("ｗ") or ("ｗ" in speech and random.random() > 0.4):   # 本人6%に対しAIは20%前後なので、常に6割は外す
        speech = _outside_quotes(speech, lambda x: re.sub(W_LAUGH, "", x))
    if over("んだよな"):
        speech = _outside_quotes(speech, lambda x: re.sub(r"(?<=[いるうくすつぬむぶぐ])んだよな", "", x))
    if over("私"):
        speech = _outside_quotes(speech, lambda x: re.sub(r"(^|[。！？\s])私(?:は|も)(?=.)", r"\1", x))
        speech = re.sub(r"(^|(?<=[。！？]))[、\s]+", "", speech)
    if "、" in speech and len(speech) <= 30 and "「" not in speech and (over("読点") or random.random() < 0.5):
        speech = speech.replace("、", "")   # 本人は読点ありが25%、AIは55〜70%
    # 本人がほとんど言わない言い回し(気になる・議論に切り替える前置き)は、直近に出ていたらその文を外す
    for key, rx in (("気になる", r"気にな"), ("議論に切替", r"議論(しよう|しましょう|始め|に切り|に入|を始)|そろそろ|雑談(は|も)(この|もう|終)")):
        if key in feats and re.search(rx, speech) and over(key):
            kept = "".join(x for x in split_sentences(speech) if not re.search(rx, x)).strip()
            if len(kept) >= 8:
                speech = kept
    return speech.strip()


# ---- 本人の過去の発言との近さで、3案から選ぶ ----
#   話す係に同じ中身を言い方違いで3案書かせ、本人の過去の発言(games_すぐれてない.jsonl)に一番近い案を選ぶ。
#   近さ = 文字1〜3個の並び(TF-IDF)の類似度が高い本人の発言5件の平均。意味は3案とも同じなので、読み間違いは増えない。
#   novoice … 3案を使わず、今まで通り1案だけ書かせる
VOICE_ON = FREE and "novoice" not in ARGS
VOICE = {"posts": None, "vecs": None, "df": None}
VOICE_EXCLUDE = set()     # bench.py が、その場面の本人の実際の返しを入れる(答えを見て選ばないため)


def _vgrams(text):
    t = re.sub(r"\s+", "", text)
    out = {}
    for n in (1, 2, 3):
        for i in range(len(t) - n + 1):
            out[t[i:i + n]] = out.get(t[i:i + n], 0) + 1
    return out


def _vvec(grams):
    n_docs = len(VOICE["posts"]) + 1
    v = {k: c * (math.log(n_docs / (VOICE["df"].get(k, 0) + 1)) + 1) for k, c in grams.items()}
    norm = math.sqrt(sum(x * x for x in v.values())) or 1.0
    return {k: x / norm for k, x in v.items()}


def voice_load():
    if VOICE["posts"] is not None:
        return
    who = FLOW_WHO[0]
    posts = []
    for g in persona_games():
        for w, t in g["day"]:
            if w == who and t.strip():
                posts.append(t.strip().replace("\n", " "))
    VOICE["posts"] = posts
    VOICE["df"] = {}
    gs = [_vgrams(x) for x in posts]
    for g in gs:
        for k in g:
            VOICE["df"][k] = VOICE["df"].get(k, 0) + 1
    VOICE["vecs"] = [_vvec(g) for g in gs]


def voice_score(text, k=5):
    voice_load()
    if not VOICE["posts"]:
        return 0.0
    v = _vvec(_vgrams(text))
    n = len(text)
    # 長さの近い本人の発言とだけ比べる(「いや」のような一言は本人にも全く同じ発言があり、短い案ばかり高く出たため)
    pool = [(u, post) for u, post in zip(VOICE["vecs"], VOICE["posts"])
            if post not in VOICE_EXCLUDE and n * 0.5 <= len(post) <= n * 2 + 4]
    if len(pool) < 20:
        pool = [(u, post) for u, post in zip(VOICE["vecs"], VOICE["posts"]) if post not in VOICE_EXCLUDE]
    sims = sorted((sum(x * u.get(a, 0.0) for a, x in v.items()) for u, post in pool), reverse=True)
    return sum(sims[:k]) / max(1, min(k, len(sims)))


def pick_voice(cands):
    """3案から、本人の過去の発言に一番近いものを選ぶ。(選んだ案, [(点, 案)...])"""
    cands = [c.strip() for c in cands]
    full = [c for c in cands if c]
    if not full:
        return "", []
    cap = BUDGET[0]
    if cap:
        fit = [c for c in full if len(c) <= cap * 1.5 + 10]
        full = fit or sorted(full, key=len)[:1]
    evasive = re.compile(r"そのままの意味|言った通り|言ったとおり|さっき言った|それ以上の意味(は)?ない|以上の意味はない")
    emo = bool(EMO_NOW[0])
    # 感情を出す場面(読む係の5)なら、爆発の案は短くても割り引かずに少し足す。場面でないのに爆発している案は引く
    short_pen = (lambda c: -0.1 if cap and cap >= 40 and len(c) < cap * 0.35 and not (emo and is_burst(c)) else 0)   # 長く言える番で一言だけの案ばかり選ばない
    lenf = (lambda c: 1.0 if emo and is_burst(c) else min(1.0, (len(c) + 3) / 18))
    emo_adj = (lambda c: (0.06 if emo else -0.05) if is_burst(c) else 0)
    # 長文の番(くじで60字超え)は、長い案を先に並べる。検証で長い案が全部落ちたときだけ短い案になる
    # (本人の60字超えの番は中央値97字。前は60〜80字の案が選ばれ、長文が出なかった)
    long_turn = bool(cap and cap > 60 and any(len(c) >= cap * 0.5 for c in full) and not (emo and any(is_burst(c) for c in full)))
    long_adj = (lambda c: 0.3 if long_turn and len(c) >= cap * 0.5 else 0)
    # 一言の案は文字の並びが少なく、似ている度合いが高く出すぎるので、短いほど割り引く
    scored = sorted(((voice_score(c) * lenf(c) + stance_bonus(c) + short_pen(c) + emo_adj(c) + long_adj(c) - (0.08 if TARGETS and evasive.search(c) else 0)
                     + (min(len(c), 40) * 0.002 if TARGETS else 0), c) for c in full),
                    reverse=True)   # 聞かれているのに、はぐらかす案は選ばない(本人は「そのままの意味」とは言わない)
    return scored[0][1], scored


# ---- 本人の「上から目線」(言い切り方)と色の言い方 ----
#   本人1248発言とAIの発言を比べて差が大きかったもの(本人 / AI):
#     一般論で言い切る「〜っていうのは〜でしょ」 6% / 0%、相手の理屈を「おかしい・無理がある・恣意的」と評価 7% / 0〜2%、
#     「普通に・当たり前・一般的に」で常識側に立つ 5% / 0〜4%、文頭「いや」 3% / 0%、丁寧語の皮肉(挨拶を除く) 12% / 2%
#     逆にAIが多すぎたもの: ぼかし「と思うけど・気がする・かも」 5% / 8〜12%、「私は」主語 5% / 8〜21%、「〜の？」 1% / 6%
#     色の言い方: 本人は「黒目・白目・村目」。「怪しい・狼っぽい・村っぽい」は合わせて0.4%しか言わない
STANCE_CATS = [
    ("一般論で言い切る(〜っていうのは〜でしょ・〜ものだよね)", r"っていうのは|というのは|ってのは|もの(だ|です|でしょ|じゃ)|もんだ|セオリー"),
    ("相手の理屈を評価して切る(おかしい・無理がある・恣意的・謎)", r"おかしい|無理(が|あ)|恣意的|こじつけ|意味(わから|分から|不明)|謎|筋(が)?通(ら|せ)|曲解|破綻|くだらな|しょうもな"),
    ("常識・当然の側に立つ(普通に・当たり前・一般的に・そもそも)", r"普通に|当たり前|当然|一般|そもそも|客観"),
    ("「いや」で切り返す", r"^いや"),
    ("丁寧語で突き放す・皮肉る(〜ですか？・〜してほしいです)", r"(です|ます|ません)(よ|ね|か)?[。？?ｗ]*$"),
]
def stance_cats():
    """台帳があるときは「一般論で言い切る」を外す(形だけ一般論の独自ルールを作ってしまったため)。"""
    return [c for c in STANCE_CATS if not (PRINCIPLES and c[0].startswith("一般論"))]


STANCE_SOFT = [
    ("ぼかし(〜と思うけど・気がする・かも)", r"と思うけど|気がする|かもしれな|かもね|かな[。？?]?$|っぽい"),
    ("「私は」を主語にする", r"私(は|の|視点|的)"),
    ("「〜の？」と柔らかく聞く", r"の[？?]$"),
    ("相手に何かを求める(〜してほしい・出してください)", r"(して|て)(ほしい|欲しい|ください|下さい)|出して|教えて"),
]
COLOR_BAD_RE = re.compile(r"怪し|狼っぽ|村っぽ|白っぽ")
GREET_RE = re.compile(r"^(おはよう|おは|こんにちは|こんばんは|よろしく|お疲れ|おつ)")
STANCE_TXT = [None]


# ---- 原則の台帳(principles_4a.json。チェック表であなたが○△×を付けたもの) ----
#   一般論の形で言い切ってよいのは台帳の use の原則だけ。台帳に無い考え方(×を付けたものを含む)は「そう考える人もいる」止まりで、一般論として言い切らない。
#   論じる係(読む係の6)が「今回の主張・使う原則・ログの根拠」を決め、話す係はそれを本人の口調で言う。
#   検証の段の7で、台帳に無い独自の決まりを一般論として言い切った案を落とす。noprinciples で無効
def _load_principles():
    if "noprinciples" in ARGS:
        return None
    try:
        return json.loads(Path("principles_4a.json").read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None


PRINCIPLES = _load_principles()


def principles_text(short=False):
    """台帳を文章にする(話す係のシステム・読む係・検証の段で使う)。"""
    if not PRINCIPLES:
        return ""
    use = "\n".join(f"{p['id']}. {p['text']}" + (f"(条件: {p['cond']})" if p.get("cond") else "") for p in PRINCIPLES.get("use", []))
    avoid = "\n".join(f"{p['id']}. {p['text']}" + ("" if short or not p.get("why") else f" → {p['why']}") for p in PRINCIPLES.get("avoid", []))
    defs = "\n".join(f"・{k}: {v}" for k, v in (PRINCIPLES.get("defs") or {}).items())
    return ("【原則の台帳: 一般論として言ってよいのはこれだけ】\n" + use
            + "\n(台帳に無い考え方は、人によって分かれるもの。一般論として言い切らない)"
            + (("\n\n【言ってはいけない一般論】\n" + avoid) if avoid else "")
            + (("\n\n【言葉の定義】\n" + defs) if defs else ""))


PLAYBOOK_AVOID_RE = re.compile(r"序盤の材料は「起点」|当然二面性|お気持ち表明・定型発言|テンプレ発言|「気がする」などの主観語|主観的な否定|村のときは早めに投票先|私はAに入れる")


def filter_playbook(body):
    """台帳で×になった考え方の行を手引きから外す(手引きは本人の考え方だが、正当性は台帳を優先する)。"""
    if not PRINCIPLES or not body:
        return body
    return "\n".join(l for l in body.splitlines() if not PLAYBOOK_AVOID_RE.search(l))


# ---- 感情の爆発(本人1248発言から) ----
#   ｗ3つ以上 1.2%・！2つ以上 1.4%・「草」だけ 1.3%・「ふざけるな」系 1.2%・「は？」「おい」0.5%。合わせて約5%(20発言に1回)
#   出る場面: 相手が同じ逸らしを繰り返す・答えない(「なんで一旦おいとくんだよ！！！…」「なんで毎回逸れるんだよｗ」)、
#   むちゃな理屈(「なんの感情を隠すんだよｗｗｗ…」「嘘をつくな！！！！」)、理不尽に黒く見られた(「何で白くないんだよふざけんな」)、
#   場が笑っている(他の人のｗｗｗ・草に「ｗｗｗｗｗｗｗ」)。出すときは2〜3発言続くことがある(「おまえが…！！！」→「ふざけるなよ！！！」)
#   ！の数は 2〜35個(中央値7)、ｗは 3〜13個(中央値7)。AIは「！！」程度で止まるので、本人の数に寄せる
BURST_RE = re.compile(r"[ｗw]{3,}|[！!]{2,}|^\s*草+\s*$|ふざけ(?:るな|んな)|^\s*は[？?]|^\s*おい\s*$")
BURST_EXCL = [2, 3, 3, 4, 5, 7, 7, 11, 12, 12, 18, 23, 35]
BURST_W = [3, 4, 5, 5, 7, 7, 9, 11, 11, 12, 13]
EMO_NOW = [""]      # 読む係が「感情:」と書いた場面の中身(空なら感情を出す場面ではない)
MINE_NOW = [[]]     # この試合の自分の発言(話す係を呼ぶ前にそろえる)


def is_burst(t):
    return bool(BURST_RE.search(t or ""))


def burst_ok(mine):
    """今、感情を爆発させてよいか。本人は約20発言に1回。続けて出すのは3発言まで。"""
    if mine and is_burst(mine[-1]):
        return sum(is_burst(t) for t in mine[-3:]) < 3
    return not any(is_burst(t) for t in mine[-12:])


def burst_quota(speech, mine):
    """爆発の割合を本人に合わせる: 出しすぎなら「！」「ｗ」1つに戻す。出すなら記号の数を本人の数に寄せる。"""
    if not is_burst(speech):
        return speech
    if not burst_ok(mine):
        speech = re.sub(r"[！!]{2,}", "！", speech)
        return re.sub(r"[ｗw]{3,}", "ｗ", speech)

    def excl(m):
        n = len(m.group(0))
        return "！" * max(n, random.choice(BURST_EXCL)) if n < 5 else m.group(0)

    def ww(m):
        n = len(m.group(0))
        return "ｗ" * max(n, random.choice(BURST_W)) if n < 5 else m.group(0)
    speech = _outside_quotes(speech, lambda x: re.sub(r"[ｗw]{3,}", ww, re.sub(r"[！!]{2,}", excl, x)))
    return speech


def burst_examples(posts, rnd):
    bad = re.compile(NOT_SHARP_RE.pattern + r"|しね|お前ら|おまえら|[:：]")
    ex = sorted({re.sub(r"([！!ｗw])\1{9,}", lambda m: m.group(1) * 10, t) for t in posts
                 if is_burst(t) and len(t) <= 45 and "\n" not in t and not bad.search(t) and t.strip() != "草"})
    rnd.shuffle(ex)
    return ex[:7]


def stance_block():
    """本人の言い切り方の割合と実例(本人の実際の発言)。起動して最初に使うときに作る(キャッシュが効くように試合中は固定)。"""
    if STANCE_TXT[0] is not None:
        return STANCE_TXT[0]
    who = FLOW_WHO[0]
    posts = [t.strip() for g in persona_games() for w, t in g["day"] if w == who and t.strip() and not GREET_RE.search(t.strip())]
    if len(posts) < 50:
        STANCE_TXT[0] = ""
        return ""
    rnd = random.Random(5)
    n = len(posts)
    lines = [f"【{who}の言い切り方(本人{n}発言から数えた割合と、実際の発言。自分の主張は、この上から目線で相手に押し付ける。言い回しはそのまま使わない)】"]
    for label, pat in stance_cats():
        rx = re.compile(pat)
        hit = [t for t in posts if rx.search(t)]
        ex = [t for t in hit if 10 <= len(t) <= 60 and "\n" not in t and not NOT_SHARP_RE.search(t)]
        rnd.shuffle(ex)
        lines.append(f"・{label}: {len(hit) / n:.0%}  例: " + " / ".join(f"「{t}」" for t in ex[:3]))
    soft = []
    for label, pat in STANCE_SOFT:
        rx = re.compile(pat)
        soft.append(f"{label} {sum(bool(rx.search(t)) for t in posts) / n:.0%}")
    lines.append("・本人がほとんどしないこと: " + "、".join(soft)
                 + "。相手にお願いしたり様子をうかがったりするより、相手の理屈のどこがおかしいかを言い切る。質問するときも答えを決めつけた形で聞く")
    dsho = sum(bool(re.search(r"でしょ|だろ", t)) for t in posts) / n
    lines.append(f"・ただし言い切りを「〜でしょ」「〜だろ」ばかりで締めない(本人は合わせて{dsho:.0%})。上の形を散らして使う。"
                 "見出しの言葉(一般論・評価・常識・皮肉)そのものは発言に書かない")
    good = sum(bool(re.search(r"黒目|白目|村目|[◯○●]目", t)) for t in posts) / n
    bad = sum(bool(COLOR_BAD_RE.search(t)) for t in posts) / n
    lines.append(f"・色の言い方: 本人は「黒目」「白目」「村目」「◯目」を使う({good:.0%})。「怪しい」「狼っぽい」「村っぽい」はほぼ言わない({bad:.1%})")
    def rate(pat):
        return sum(bool(re.search(pat, t)) for t in posts) / n
    lines.append(f"・言葉づかい: 本人は「考察」({rate('考察'):.0%})「要素」({rate('要素'):.0%})と言い、「理由」「材料」「根拠」は合わせて{rate('理由|材料|根拠'):.0%}しか使わない。"
                 f"「〜っていうのは」「〜に対して」({rate('に対して'):.0%})「〜のであれば」({rate('のであれば'):.0%})「まぁ」({rate('まぁ|まあ'):.0%})「〜だろ」({rate('だろ'):.0%})はよく使う。"
                 f"相手を「〇〇さん」と呼ぶこともある({rate('[^ぁ-ん]さん'):.0%})。"
                 "「〜って言うけど」「〜しただけで」「まだ〜出てない」「先に〜」「中身」は本人はほとんど使わない")
    lines.append("・具体例で押す: 本人は長い主張の4分の1くらいで、主張を具体的な形にして押す。"
                 "相手の理屈を別の発言に当てはめる(「仮にそれが点数稼ぎだとするのであれば、『Aさんは白くも黒くもない』って発言も貴方視点だと点数稼ぎに捉えられるんじゃないの」)、"
                 "たとえ(「じゃんけんで親指から中指まで全部たてて全部に勝てる！って奴と同じやろ」「例えば12bでは黒出し占いとかは3番目とかで露出しないと遅延を取られるよね」)、"
                 "頭の中の言葉を作って見せる(「議論で突拍子もない返答がきたら『意味分からないから人外目かな？』って思うんじゃない？」)、"
                 "選択肢を並べる(「〜とか〜とかの3択しかない」)。読解メモの【主張の設計】に具体例があれば、長めの案ではそれを使う")
    ex = burst_examples(posts, rnd)
    if ex:
        lines.append(f"・感情の出し方: 本人は呆れと笑いを記号ごと爆発させる(ｗ3つ以上 {rate('[ｗw]{3,}'):.1%}・！2つ以上 {rate('[！!]{2,}'):.1%}・"
                     f"「草」だけ {rate('^草+$'):.1%}・「ふざけるな」系 {rate('ふざけ(るな|んな)'):.1%}、合わせて約{sum(is_burst(t) for t in posts) / n:.0%})。例: "
                     + " / ".join(f"「{t}」" for t in ex)
                     + "。出すのは、相手が同じ逸らしを繰り返す・聞いたことに答えない・むちゃな理屈を言い張る・理不尽に自分が黒く見られた・場が笑っている、のどれかのときだけ。"
                     "爆発は短い一言にして(「！」はたくさん、「ｗ」は5個以上)、理屈は付けないか別の発言にする。相手への悪口(死ね・馬鹿など)にはしない")
    STANCE_TXT[0] = "\n".join(lines)
    return STANCE_TXT[0]


_COLOR_TAIL = {"んだけど": "なんだけど", "んだよな": "なんだよな", "んだよね": "なんだよね", "んだよ": "なんだよ", "けど": "だけど",
               "と思う": "だと思う", "よね": "だよね", "よな": "だよな", "よ": "だよ", "でしょ": "でしょ", "のは": "なのは",
               "って": "って", "し": "だし", "から": "だから", "ね": "だね", "な": "だな",
               "と思うけど": "だと思うけど", "なら": "なら", "かな": "かな", "かも": "かも", "って": "って", "と思います": "だと思います", "と思うよ": "だと思うよ", "です": "です", "ですね": "ですね", "": ""}


def color_words(speech):
    """「怪しい・狼っぽい・村っぽい」を本人の言い方(黒目・村目)にする。言い換えられない形はそのまま。"""
    if not COLOR_BAD_RE.search(speech or ""):
        return speech
    tails = "|".join(sorted((re.escape(k) for k in _COLOR_TAIL if k), key=len, reverse=True))

    def fix(x):
        def sub(m):
            word = {"怪し": "黒目", "狼っぽ": "黒目", "村っぽ": "村目", "白っぽ": "白目"}[m.group(1)]
            tail = m.group(2) or ""
            return word + _COLOR_TAIL.get(tail, tail)
        x = re.sub(r"(怪し|狼っぽ|村っぽ|白っぽ)い(?:(" + tails + r")|(?=[。、！？!?ｗ\s]|$))", sub, x)
        x = re.sub(r"(怪し|狼っぽ|村っぽ|白っぽ)い(?=[\u4e00-\u9fff\u30a0-\u30ff])",
                   lambda m: {"怪し": "黒目", "狼っぽ": "黒目", "村っぽ": "村目", "白っぽ": "白目"}[m.group(1)] + "の", x)   # 「怪しい人」→「黒目の人」
        x = re.sub(r"(怪し|狼っぽ|村っぽ|白っぽ)く見え", lambda m: {"怪し": "黒目", "狼っぽ": "黒目", "村っぽ": "村目", "白っぽ": "白目"}[m.group(1)] + "に見え", x)
        return x
    return _outside_quotes(speech, fix)


def stance_bonus(text):
    """本人に多い言い切り方なら少し足し、本人に少ないぼかし・柔らかい問い・色の言い方なら少し引く(3案の選択用)。"""
    b = sum(0.02 for _, pat in stance_cats() if re.search(pat, text))
    b = min(b, 0.04)
    b -= sum(0.02 for _, pat in STANCE_SOFT if re.search(pat, text))
    if COLOR_BAD_RE.search(text):
        b -= 0.03
    if re.search(r"って言うけど|って言うなら|ただけで|まだ.{0,6}出てない|先に|中身|謎なんだけど|理由が", text):
        b -= 0.02    # AIに多く、本人はほとんど使わない言い回し
    if re.search(r"でしょ|だろ", text):
        b -= 0.005   # 「でしょ」ばかりにならないよう少しだけ引く(本人9%)
    if re.search(r"(です|ます|ません|ですが|ますが)", text) and len(text) > 25:
        b -= 0.02    # 長い丁寧文は本人らしくない(本人の丁寧語は短い突き放し。AIは35%まで増えた)
    return b


# ---- 本人の表記と言い回しの癖(本人1248発言とAIの約700発言の比較から) ----
#   本人に多い表記: 「出来る」(3.0% / AI 0%)・「事」(8.3% / 3.4%)・「訳」(1.9% / 0.1%)・「良い」(2.4% / 0%)・「〜のであれば」(2.2% / 0%)
#   AIに多い表記: 「できる」「こと」「わけ」「いい」「〜なら、」(本人0.4% / AI 8.5%)
#   後処理で、本人の割合くらいになるように確率で置き換える(引用の中は触らない)
HYOUKI_ON = "nohyouki" not in ARGS


def hyouki(speech):
    if not HYOUKI_ON or not speech:
        return speech

    def fix(x):
        x = re.sub(r"でき(る|ない|た|て|れ|ま|そう|なく)", lambda m: ("出来" if random.random() < 0.75 else "でき") + m.group(1), x)
        x = re.sub(r"(?<![まひ])こと(?!ば|わざ)", lambda m: "事" if random.random() < 0.75 else "こと", x)
        x = re.sub(r"わけ(?=じゃ|で|が|だ|ない|では|には|なの|です|な|に)", lambda m: "訳" if random.random() < 0.8 else "わけ", x)
        x = re.sub(r"(?:(?<=^)|(?<=[でもがはをとてにの、。\s]))いい(?=[。、よねけしんじかとだ\s]|$)",
                   lambda m: "良い" if random.random() < 0.6 else "いい", x)
        x = re.sub(r"(?<=[うくすつぬふむゆるぐずづぶぷいた])なら、", lambda m: "のであれば、" if random.random() < 0.5 else "なら、", x)
        return x
    return _outside_quotes(speech, fix)


SLIM_OUTPUT_FREE = ("【出力】\n1行目: 【読み取り】今回話しかける相手(1人)と、【読解メモ】のどの点を受けるか、その人に自分が前に聞いたこと。読解メモと食い違うことは言わない\n"
                    "2行目: <発言>チャットに書く本文</発言>\n"
                    "3行目: 【見立て】名前=人狼っぽさ(0〜100), 名前=… / 理由: 一言")
SLIM_OUTPUT_FREE_3 = ("【出力】\n1行目: 【読み取り】今回話しかける相手(1人)と、【読解メモ】のどの点を受けるか、その人に自分が前に聞いたこと。読解メモと食い違うことは言わない\n"
                      "2〜4行目: <発言>…</発言> を3つ。中身(言うこと・相手・主張)は同じで、言い方と長さだけを変えた3通り(1つは短い言い方、1つは【今回の長さ】いっぱいまで理由を言い切る形、1つは【言い切り方】のどれかの形(一般論で言い切る・相手の理屈を評価して切る・常識の側に立つ・「いや」で切り返す)。3つとも文末を変える。丁寧語は「わかんないんですか。」のような短い突き放しのときだけ使い、「〜と思いますが」「お聞きしますが」のような長い丁寧文にはしない)。"
                      "どれも【今回の長さ】以内。何も言わない方が自然なら3つとも空にする\n"
                      "5行目: 【見立て】名前=人狼っぽさ(0〜100), 名前=… / 理由: 一言")


def speak_effort():
    if SPEAK_EFFORT == "auto":
        return "medium" if SCENE_TAG[0] in EFFORT_UP_TAGS else "low"
    return SPEAK_EFFORT


def build_prompt_slim(name, role, msgs, alive_names, memo=None, sim=True):
    """話す係用の最小のプロンプト: 役職・今日のログ・「〈自分〉ならここで何と言うか」だけ。"""
    vis = visible_log(current_game(msgs))
    MINE_NOW[0] = [m["text"] for m in current_game(msgs) if m["from_user"] == name]
    lines = []
    for i, m in enumerate(vis):
        if m["from_user"] == "鯖" and not re.search(r"朝になりました|投票|死亡|処刑", m["text"]):
            continue
        to = "" if m["to_user"] == "ALL" else f"→{m['to_user']}"
        lines.append(f"#{i + 1} {m['from_user']}{to}: {m['text'].replace(chr(10), ' / ')}")   # 貼り付けの改行で別の人の発言に見えないように
    secret = private_info(msgs, name)
    phase = PHASE.get("name")
    switch = {"序盤": ("(雑談に乗ってよい時間。材料が無く色は落ちにくいので、人の印象を詰めない。誰かが議論を始めたら乗るが、"
                     "序盤の材料(黙っている・挨拶の早さ・言い回しなど)は起点として軽く出すだけにする)"),
              "中盤": "(雑談が続いていても、無理に議論へ切り替えなくてよい。雑談に乗りながら、引っかかる発言があればそこを突く)",
              "終盤": "(投票が近い。雑談より、誰に入れるかとその理由)"}.get(phase, "")
    counts = {}
    for m in vis:
        if m["from_user"] not in ("鯖", "人狼") and m["to_user"] == "ALL" and not GREET_ONLY_RE.fullmatch(m["text"]):
            counts[m["from_user"]] = counts.get(m["from_user"], 0) + 1
    cnt_txt = ", ".join(f"{n} {counts.get(n, 0)}回" for n in alive_names)
    head = (f"あなた={name} / 役職={role or '不明'} / 生存={', '.join(alive_names)} / 挨拶以外の発言数: {cnt_txt}"
            + (f" / 昼の{phase}{switch}" if phase else "") + (f"\n{secret}" if secret else ""))
    hint = ""
    if memo and memo.get("text"):
        # 考える係(Opusなど)の結論だけを短く渡す。言い回しや「言うこと」は渡さない(話す係が流れに合わせて自分の言葉で話すため)
        # 数字だけ渡す(前は理由や違和感の文も渡していたが、古い分析の言い分(「〇〇しか言ってない」など)を
        # 流れが変わった後もくり返してしまったため)
        keep = [re.split(r"\s*/\s*理由", l.strip())[0][:80] for l in memo["text"].splitlines()
                if l.strip().startswith("【見立て】")]
        if keep:
            hint = ("\n\n【少し前に頭の中で付けた数字(人狼っぽさ。今のログの方が優先)】\n" + keep[0])
    tics = repeated_phrases([m["text"] for m in vis if m["from_user"] == name][-6:], list(alive_names) + [name])
    note = ("\n(何度も使った言い回しは使わない: " + "、".join(tics) + ")") if tics else ""
    if not BANK["rows"] and not BANK.get("tried"):
        BANK["tried"] = True
        load_bank()
    sim = similar_block(vis, name) if sim else ""
    # キャッシュが効くように、毎回同じ部分(朝からのログ)を先に、毎回変わる部分(発言数・見立て・似た場面・指示)を後ろに置く。
    # ログは10発言ずつの塊に分け、塊が埋まった所までをキャッシュする(ログは後ろに伸びるだけなので、前の塊は毎回同じ)
    if len(lines) > 400:
        lines = lines[((len(lines) - 400) // LOG_CHUNK + 1) * LOG_CHUNK:]
    n_full = len(lines) // LOG_CHUNK * LOG_CHUNK
    chunks = ["\n".join(lines[i:i + LOG_CHUNK]) + "\n" for i in range(0, n_full, LOG_CHUNK)]
    log_head = "【今日のログ(朝から全部・古い順・最後が最新)】\n"
    # まだ答えていない自分あての質問をはっきり見せる(「なんで重要なの？」と何度聞かれても答えずに詰め続けたため)
    openq = unanswered_to_me(msgs, name) if sim else []
    if sim:
        TARGETS[:] = [(m["from_user"], m["text"]) for m in openq]   # 投稿したら答えたことにする
    qtxt = ("\n\n【まだ答えていない、自分あての質問(この発言の最初に、まず一文で答える。答えずに聞き返したり詰め続けたりしない)】\n"
            + "\n".join(f"・{m['from_user']}: {m['text'][:90]}" for m in openq)) if openq else ""
    rest = ("\n".join(lines[n_full:]) + "\n\n" + head + qtxt + hint + sim
            + f"\n\nお手本の{FLOW_WHO[0]}なら、ログの流れの最後でどう考え、どう返すか。{name}として次の1発言を書く。"
              "何も言わない方が自然なら<発言></発言>を空にする。" + note + (style_prompt(msgs, name) if sim else "")
            + "\n\n" + ((SLIM_OUTPUT_FREE_3 if VOICE_ON else SLIM_OUTPUT_FREE) if FREE else SLIM_OUTPUT))
    if chunks:
        return log_head + CACHE_BLOCK.join(chunks) + CACHE_SPLIT + rest
    return log_head + rest


def system_prompt(context, debate=True):
    """毎回同じ部分(ルール・固定のお手本)を先頭に、毎回変わる部分(用語)を後ろに置く。
    先頭が前回と同じだと、Ollamaはその部分を読み直さずに使い回すので速くなる。
    debate=False(開始前など)のときは、攻撃的な指示とお手本を入れない。"""
    if debate and SLIM:
        if PLAYBOOK[0] is None:
            PLAYBOOK[0] = load_playbook()
        parts = [SLIM_SYSTEM.format(name=SLIM_NAME[0] or "あなた", style=STYLE, who=FLOW_WHO[0],
                                    role_note=ROLE_NOTES.get(SLIM_ROLE[0], ROLE_NOTES["村人"]))]
        if PLAYBOOK[0]:
            parts.append(PLAYBOOK[0])
            unused = book_words_unsaid()
            if unused:
                parts.append("(手引きの言葉は考えるための言葉。次の言葉は本人が実際の発言では使っていないので、発言には使わず普通の言い方にする: "
                             + "、".join(unused) + ")")
        if SHARP[0] is None:
            sl = sharp_lines()
            SHARP[0] = (f"【{FLOW_WHO[0]}の実際のツッコミ・煽り(この強さ・この短さで言う。丸くしない。言い回しはそのまま使わない)】\n"
                        + "\n".join(f"・{t}" for t in sl)) if sl else ""
        if SHARP[0] and (not FREE or FREE_FULL):
            parts.append(SHARP[0])
        if FREE and stance_block():
            parts.append(stance_block())
        if PRINCIPLES:
            parts.append(principles_text()
                         + "\n(一般論の形「〜っていうのは」「〜ものだよ」「普通は」「当然」「村も狼もやる」で言い切るのは、台帳の原則に当たるときだけ。"
                           "台帳に無いなら、一般論を作らずに、ログの事実と相手の発言どうしの食い違いで言う)")
        if FLOW_BLOCK and (not FREE or FREE_FULL):
            parts.append(FLOW_BLOCK)
        if RULES:
            parts.append(RULES)
        return "\n\n".join(parts), 0
    if debate:
        parts = [DEBATE_SYSTEM]
        examples = FIXED_BLOCK if FIXED_EXAMPLES else choose_examples()
        if examples:
            parts.append(examples)
        if FLOW_BLOCK:
            parts.append(FLOW_BLOCK)
    elif PERSONAS[PERSONA].get("chat_full"):
        parts = [CHAT_SYSTEM_FULL]
        examples = FIXED_BLOCK if FIXED_EXAMPLES else choose_examples()
        if examples:
            parts.append(examples)
    else:
        parts = [CHAT_SYSTEM]
    if RULES:
        parts.append(RULES)
    if debate and STYLE_GUIDE and not PERSONAS[PERSONA].get("light"):
        parts.append(STYLE_GUIDE)   # light の人格では話す係に渡さない(考える係だけが使う)
    if debate and LESSONS:
        parts.append(LESSONS)
    words = pick_glossary(context)
    if words:
        parts.append("【用語】\n" + "\n".join(words))
    return "\n\n".join(parts), len(words)


def visible_log(msgs):
    """AIに見せるログを整える。誤解のもとになる行を除く。"""
    result = []
    for m in msgs:
        # 「人狼: アォ----ン」は夜に人狼同士が会話した合図で、誰かの発言ではない(叫んだと誤解するので除く)
        if m["from_user"] == "人狼" and m["text"].startswith("アォ"):
            continue
        # 「○○→GM: 投票@…」は本人にしか見えない操作記録なので除く
        if m["to_user"] == "GM":
            continue
        result.append(m)
    return result


def current_game(msgs):
    """直近の試合の分だけを返す(前の試合の情報を混ぜない)。
    「あなたは【○○】です」「役職設定【…】」は「ゲームを開始します」の直前に出るので、それも含める。"""
    for i in range(len(msgs) - 1, -1, -1):
        if msgs[i]["from_user"] == "鯖" and "ゲームを開始します" in msgs[i]["text"]:
            start = i
            while start > 0 and msgs[start - 1]["from_user"] == "鯖" and (
                    "あなたは【" in msgs[start - 1]["text"] or "役職設定【" in msgs[start - 1]["text"]):
                start -= 1
            return msgs[start:]
    return msgs


def game_events(msgs):
    """試合の出来事をログから拾う: 処刑された人・死んだ人・勝敗・各自の役職。"""
    g = current_game(msgs)
    executed, dead, roles, winner = [], [], {}, None
    for m in g:
        if m["from_user"] != "鯖":
            continue
        t = m["text"]
        for r in re.finditer(r"投票の結果【(.+?)】さんが処刑されます", t):
            executed.append(r.group(1))
        r = re.match(r"(.+?)さんが死亡しました", t)
        if r:
            dead.append(r.group(1))
        r = re.search(r"【(.+?チーム)】の勝利", t)
        if r:
            winner = r.group(1)
        r = re.search(r"あなたは【(.+?)】です", t)
        if r and m["to_user"] not in ("ALL", "人狼"):
            roles[m["to_user"]] = r.group(1)
    bitten = [d for d in dead if d not in executed]
    return {"executed": executed, "bitten": bitten, "winner": winner, "roles": roles}


def events_text(msgs, finished=False):
    """これまでの出来事を文章にする。finished=True なら試合結果(勝敗・全員の役職)も入れる。"""
    e = game_events(msgs)
    lines = []
    if e["bitten"]:
        lines.append(f"夜に死んだ人(噛まれた人): {', '.join(e['bitten'])}")
    if e["executed"]:
        lines.append(f"投票で処刑された人: {', '.join(e['executed'])}")
    if finished:
        if not e["winner"]:
            return ""
        lines.insert(0, f"勝敗: {e['winner']}の勝利")
        if e["roles"]:
            lines.append("全員の役職: " + ", ".join(f"{p}={r}" for p, r in e["roles"].items()))
    return "\n".join(lines)


RESULT_RE = re.compile(r"(?:処刑された)?(.+?)さんは(人狼ではありません|人狼ではない|人狼です|人狼でした)")


def my_results(msgs, name):
    """鯖から自分宛てに届いた占い・霊能結果を {名前: True(人狼)/False(人狼ではない)} にする。"""
    res = {}
    for m in current_game(msgs):
        if m["from_user"] == "鯖" and m["to_user"] == name:
            r = RESULT_RE.search(m["text"])
            if r:
                res[r.group(1)] = r.group(2) in ("人狼です", "人狼でした")   # True=人狼(黒)
    return res


def facts_text(role, results, alive_names):
    """AIに渡す「確定している事実」と「今日の方針」。推理をAIに任せず、Python側で結論を決めておく。"""
    if not results:
        return ""
    lines = [f"{p}: {'人狼(黒)' if b else '人狼ではない(白)'}" for p, b in results.items()]
    text = f"【確定している事実】(あなたは{role}。これは本物の結果)\n" + "\n".join(lines) + "\n"
    blacks = [p for p, b in results.items() if b and p in alive_names]
    whites = [p for p, b in results.items() if not b]
    if blacks:
        text += (f"【今日の方針】人狼は{blacks[0]}で確定している。{blacks[0]}を吊るよう全員に呼びかける。"
                 f"{blacks[0]}以外の人を人狼だと言ってはいけない。\n")
    elif whites:
        text += f"【今日の方針】{'・'.join(whites)}は人狼ではないので疑わない。残りの人から人狼を探す。\n"
    return text


def board_text(msgs, name, alive_names):
    """盤面の要約。小さいモデルが存在しない人物を作ったりしないよう、Pythonで事実を並べる。"""
    setting = ""
    for m in current_game(msgs):
        r = re.search(r"役職設定【(.+?)】", m["text"])
        if r:
            setting = r.group(1)
    others = [p for p in alive_names if p != name]
    text = "【盤面】\n"
    if setting:
        text += f"役職の内訳: {setting}\n"
    text += f"生きている人: {', '.join(alive_names)}(この村にいるのはこの人たちだけ。他の名前を出さない)\n"
    text += f"あなた({name})以外で生きている人: {', '.join(others)}\n"
    ev = events_text(msgs)
    if ev:
        text += ev + "\n"
    special = [x for x in ("占い師", "霊能者", "狩人", "狂人", "猫又", "共有者") if x in (setting or "")]
    if "役欠け:あり" in (setting or "") and special:
        text += (f"役欠けあり: 初日犠牲者が{'・'.join(special)}のどれかを持っていた可能性がある。"
                 "つまり対抗が出ていなくても、COが偽の可能性は残る\n")
    elif "役欠け:あり" in (setting or ""):
        text += "役欠けあり: ただしこの村の役職は人狼と村人だけなので、初日犠牲者は村人。役欠けで考えることは何もない\n"
    wolves = re.search(r"人狼-(\d+)", setting or "")
    if wolves:
        n = int(wolves.group(1))
        text += f"人狼は全部で{n}人。あなた以外の生きている{len(others)}人の中に人狼がいる(自分が人狼の場合を除く)\n"
    return text


def private_info(msgs, name):
    """鯖から自分だけに届いた情報(占い結果など)。今の試合の分だけ。"""
    return [m["text"] for m in current_game(msgs)
            if m["from_user"] == "鯖" and m["to_user"] == name and "あなたは【" not in m["text"]
            and not RESULT_RE.search(m["text"])]   # 結果は【確定している事実】で別に渡す


def human_talk(msgs, name=None):
    """今の試合で、人間(鯖・遠吠え以外)が全体に向けて書いた発言。name を渡すとその人を除く。"""
    return [m for m in current_game(msgs) if m["from_user"] not in ("鯖", "人狼", name)
            and m["to_user"] == "ALL"]


def new_human_count(msgs, name):
    """自分の最後の発言より後に、他の人が書いた発言の数。"""
    talk = [m for m in current_game(msgs) if m["from_user"] not in ("鯖", "人狼") and m["to_user"] == "ALL"]
    n = 0
    for m in reversed(talk):
        if m["from_user"] == name:
            if m["text"] in REACTED:
                continue        # 反射の反応(「？」など)は返事に数えない
            break
        n += 1
    return n


def quotes_me(text, mine):
    """text に自分の過去の発言が QUOTE_MIN 文字以上そのまま入っているか。"""
    for t in mine:
        t = re.sub(r"\s", "", t)
        for i in range(0, max(1, len(t) - QUOTE_MIN + 1), 4):
            piece = t[i:i + QUOTE_MIN]
            if len(piece) == QUOTE_MIN and piece in re.sub(r"\s", "", text):
                return True
    return False


def is_question(sentence):
    s = sentence.strip()
    return s.endswith(("?", "？")) or bool(re.search(
        r"(聞きたい|知りたい|教えて|聞かせて|ですか|ますか|でしょうか|てもらえると|てほしい|ください)", s))


def my_questions(msgs, name):
    """今の試合で自分がした質問の文。"""
    out = []
    for m in current_game(msgs):
        if m["from_user"] == name:
            out += [t.strip() for t in split_sentences(m["text"]) if is_question(t)]
    return out


def drop_asked(speech, asked, names=()):
    """前にした質問とほぼ同じ質問の文を取り除く(同じことを何度も聞かない)。"""
    if re.fullmatch(r"\s*(?:[はえん]?[？?]+[ｗw]?|…+[？?]?)\s*", speech or ""):
        return speech, []   # 「？」だけの聞き返しは中身が無いので比べない
    def core(t):
        for n in names:
            t = t.replace(n, "")
        return re.sub(r"[\s、。!?！？さん]", "", t)
    past = [core(q) for q in asked]
    kept, dropped = [], []
    for t in split_sentences(speech):
        if is_question(t) and any(similar(core(t), q) >= 0.5 for q in past if len(q) >= 6):
            dropped.append(t.strip())
        else:
            kept.append(t)
    return "".join(kept).strip(), dropped


ANSWERED = set()        # 答えた質問 (発言者, 本文)
TARGETS = []            # 今作っている発言で答える予定の質問
IGNORED_RE = re.compile(r"(シカト|無視|スルー|返答まだ|答えて|答えろ|質問に答え)")


def unanswered_to_me(msgs, name, window=15):
    """自分あての質問・呼びかけのうち、まだ答えていないもの(古い順)。
    自分あて = 名前が入っている / 自分の発言を引用している / 自分の発言の直後の質問。
    答えた = その質問を【今やること】に入れて作った発言を投稿した(ANSWERED)、
             またはその後の自分の発言が、質問した人の名前から始まっている。"""
    cg = current_game(msgs)
    morning = max((i for i, m in enumerate(cg) if m["from_user"] == "鯖" and "朝になりました" in m["text"]), default=0)
    # 前の日の質問はもう答える場面ではないので、今日の分だけを見る
    g = [m for m in cg[morning:] if m["from_user"] not in ("鯖", "人狼") and m["to_user"] == "ALL"]
    g = g[-window:]
    mine = [m["text"] for m in current_game(msgs) if m["from_user"] == name and m["to_user"] == "ALL"]
    open_q = []
    for i, m in enumerate(g):
        if m["from_user"] == name:
            continue
        t = m["text"]
        prev_mine = any(x["from_user"] == name for x in g[max(0, i - 2):i])
        senders = {x["from_user"] for x in g} - {name, m["from_user"]}
        if any(n in t for n in senders):
            prev_mine = False   # 別の人の名前を呼んでいる質問は、自分あてではない
        to_me = (name in t or quotes_me(t, mine) or IGNORED_RE.search(t)
                 or (prev_mine and re.search(r"[?？]", t)))
        if not to_me:
            continue
        if (m["from_user"], t) in ANSWERED:
            continue
        if len(g) - i > 6:
            continue    # 6発言以上前の質問は、もう流れが変わっているので無理に答えに戻らない
        later_mine = [x["text"] for x in g[i + 1:] if x["from_user"] == name]
        if any(x.startswith(m["from_user"]) for x in later_mine):
            continue    # その人の名前を呼んで返事をしている → 答えた
        open_q.append(m)
    return open_q


STANCE_RE = re.compile(r"【見立て】(.*)")


def parse_stance(line, names):
    """「【見立て】A=70, B=30 / 理由: …」を ({名前: 数字}, 理由) にする。"""
    body = line.split("/", 1)
    scores = {}
    for n in sorted(names, key=len, reverse=True):
        r = re.search(re.escape(n) + r"\s*[=＝:：]\s*(\d{1,3})", body[0])
        if r:
            scores[n] = min(100, int(r.group(1)))
    why = re.sub(r"^\s*理由\s*[:：]\s*", "", body[1]).strip() if len(body) > 1 else ""
    return scores, why


def stance_text(stance):
    if not stance or not stance.get("scores"):
        return ""
    s = ", ".join(f"{n}={v}" for n, v in sorted(stance["scores"].items(), key=lambda x: -x[1]))
    return (f"\n\n【あなたの前回の見立て(人狼っぽさ)】{s}"
            + (f" / 理由: {stance['why']}" if stance.get("why") else "")
            + "\nこれと食い違うことを言わない。新しい具体的な根拠が出たときだけ変え、変えるなら発言の中で理由を言う。")


ANGLES = [
    ("反論", "相手の直前の主張の、論理の穴や前提のおかしさを1つ具体的に突く"),
    ("盤面", "役職の内訳・対抗COの有無・役欠けなど、盤面の構造から自分の主張を支える"),
    ("発言精査", "相手の過去の発言から、人狼らしい動き(論点ずらし・他人への印象操作など)を1つ拾う"),
    ("第三者へ", "まだ判断を決めていない人に向けて、どちらを信じるべきかの判断材料を短く整理する"),
    ("問い返し", "相手が答えにくい、核心を突く質問を1つだけする"),
    ("視点", "相手が本当に村人だったら取るはずの行動と、実際の行動の違いを指摘する"),
    ("暴論", "あえて突拍子もない極論や二択を1つ、自分の意見として投げて、誰がどう反応するかを見る(反応自体を材料にする)。統計・データなど無い事実は使わない"),
]


def pick_angle(used):
    """直近に使っていない切り口を選ぶ(同じ主張の繰り返しを防ぐ)。"""
    for a in ANGLES:
        if a[0] not in used[-3:]:
            return a
    return random.choice(ANGLES)


