def talk_stats(msgs, name):
    """Pythonで数えられる事実(誰がどれだけ意見を出しているか)。考える係の材料にする。"""
    talk = [m for m in visible_log(current_game(msgs))
            if m["from_user"] not in ("鯖", "人狼") and m["to_user"] == "ALL"]
    mornings = [i for i, m in enumerate(current_game(msgs)) if m["from_user"] == "鯖" and "朝になりました" in m["text"]]
    rows = []
    for who in dict.fromkeys(m["from_user"] for m in talk):
        mine = [m["text"] for m in talk if m["from_user"] == who]
        q = sum(1 for t in mine if re.search(r"[?？]\s*($|>|＞|→)", t))
        short = sum(1 for t in mine if len(t) <= 8)
        opinion = sum(1 for t in mine if re.search(r"黒|白|吊|狼|村目|人外|怪し|投票", t) and not re.search(r"[?？]\s*($|>|＞|→)", t))
        rows.append(f"・{who}{'(自分)' if who == name else ''}: 発言{len(mine)}回 / 質問{q}回 / 一言だけ{short}回 / 意見らしい発言{opinion}回")
    return "【数えた事実(Pythonで集計)】\n" + "\n".join(rows) if rows else ""


def roles_text(msgs):
    """この村の配役(役職設定【…】)。存在しない役職の話をしないように毎回渡す。"""
    g = current_game(msgs)
    r = next((re.search(r"役職設定【(.+?)】", m["text"]) for m in reversed(g)
              if m["from_user"] == "鯖" and "役職設定【" in m["text"]), None)
    if not r:
        return ""
    body = r.group(1)
    have = set(re.findall(r"([^\-,、:：]+?)-\d+", body))
    absent = [x for x in ("占い師", "霊能者", "狩人", "狂人", "猫又", "共有者") if x not in have]
    return (f"この村の配役: {body}" + (f"(この村に{'・'.join(absent)}はいない。いないゲームの役職の話はしない。"
                                     "ただし「判定役」「進行役」「まとめ役」のような議論の中の役割は役職ではないので、普通の提案として扱う)"
                                     if absent else "") + "\n")


