class LogKeeper:
    """画面のログを手元に足し続ける。サイトが古い発言を画面から消しても、過去の発言をさかのぼって読めるようにする。
    それ以外の操作はそのまま Zinro に任せる。"""

    def __init__(self, inner):
        self.inner = inner
        self.hist = []
        self.seen = 0

    def __getattr__(self, k):
        return getattr(self.inner, k)

    def _merge(self, dom):
        h, n = self.hist, len(dom)
        if not h:
            h.extend(dom)
            return
        if len(h) >= n and h[-n:] == dom:
            return                                  # 変化なし(よくある)
        for k in range(min(len(h), n), 0, -1):      # 前回の末尾と今回の先頭が重なる分を探す
            if h[-k:] == dom[:k]:
                h.extend(dom[k:])
                return
        tail = h[-(n + 5):]
        for i in range(len(tail) - n + 1):          # 画面の描き直しで表示が減っただけ
            if tail[i:i + n] == dom:
                return
        h.extend(dom)                               # 重ならない = 新しい試合で画面のログが消えた

    def messages(self):
        dom = self.inner.messages()
        if dom is None:
            return None
        if dom:
            self._merge(dom)
        return list(self.hist)

    def new_messages(self):
        all_msgs = self.messages()
        if all_msgs is None:
            return []
        new = all_msgs[self.seen:]
        self.seen = len(all_msgs)
        return new

    def skip_history(self):
        msgs = self.messages()
        self.seen = len(msgs) if msgs else 0


z = LogKeeper(z)
z.skip_history()
